"""
Check that links in the generated HTML documentation resolve.

Local links must point at an existing file (and an existing anchor if a
fragment is given). HTTP(S) links must return a non-error status.
"""

import argparse
import os
import sys
import urllib.error
import urllib.request
from concurrent.futures import ThreadPoolExecutor
from html.parser import HTMLParser
from pathlib import Path
from urllib.parse import unquote, urldefrag, urlparse

USER_AGENT = "Mozilla/5.0 (compatible; numbers-parser-link-check)"
SKIPPED_SCHEMES = {"mailto", "tel", "javascript", "data"}

# Pages generated by Sphinx that contain no useful links to verify
SKIPPED_FILES = {"genindex.html", "py-modindex.html", "search.html"}


class LinkParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.links = []
        self.anchors = set()

    def handle_starttag(self, tag, attrs):
        attrs = dict(attrs)
        for name in ("id", "name"):
            if attrs.get(name):
                self.anchors.add(attrs[name])
        if tag in ("a", "link") and attrs.get("href"):
            self.links.append(attrs["href"])
        elif tag in ("img", "script") and attrs.get("src"):
            self.links.append(attrs["src"])


def parse(path):
    parser = LinkParser()
    parser.feed(path.read_text(encoding="utf-8", errors="replace"))
    return parser


def check_external(url, timeout):
    """Return an error string, or None if the URL resolves."""
    for method in ("HEAD", "GET"):
        request = urllib.request.Request(  # noqa: S310
            url, method=method, headers={"User-Agent": USER_AGENT}
        )
        try:
            with urllib.request.urlopen(request, timeout=timeout):  # noqa: S310
                return None
        except urllib.error.HTTPError as e:
            # Some servers reject HEAD; retry with GET before reporting
            if method == "GET" or e.code not in (400, 403, 405, 501):
                return f"HTTP {e.code}"
        except (urllib.error.URLError, TimeoutError, OSError) as e:
            return str(getattr(e, "reason", e))
    return "unresolved"  # pragma: no cover


def main():
    ap = argparse.ArgumentParser(description=__doc__)
    ap.add_argument("build_dir", nargs="?", default="docs/build", type=Path)
    ap.add_argument("--timeout", type=float, default=15.0)
    ap.add_argument("--workers", type=int, default=16)
    ap.add_argument("--offline", action="store_true", help="skip HTTP(S) links")
    args = ap.parse_args()

    root = args.build_dir.resolve()
    html_files = sorted(
        p for p in root.rglob("*.html") if p.name not in SKIPPED_FILES and "_sources" not in p.parts
    )
    if not html_files:
        print(f"Links check: no HTML files found in {root}", file=sys.stderr)
        return 1

    parsed = {}
    errors = []
    external = {}  # url -> [source files]

    def anchors_for(path):
        if path not in parsed:
            parsed[path] = parse(path)
        return parsed[path].anchors

    for page in html_files:
        _ = anchors_for(page)
        for href in parsed[page].links:
            href = href.strip()  # noqa: PLW2901
            url = urlparse(href)
            if url.scheme in SKIPPED_SCHEMES:
                continue
            rel = page.relative_to(root)
            if url.scheme in ("http", "https"):
                external.setdefault(urldefrag(href)[0], []).append(rel)
                continue
            if url.scheme or url.netloc:
                continue

            if url.path:
                path = unquote(url.path)
                target = (
                    root / path.lstrip("/") if path.startswith("/") else page.parent / path
                ).resolve()
                if target.is_dir():
                    target = target / "index.html"
                elif not target.exists():
                    # The theme emits extensionless, site-root-relative page links
                    for base in (page.parent, root):
                        candidate = (base / f"{path.lstrip('/')}.html").resolve()
                        if candidate.exists():
                            target = candidate
                            break
            else:
                target = page
            if not target.exists():
                errors.append(f"{rel}: missing file '{href}'")
            elif (
                url.fragment
                and target.suffix == ".html"
                and unquote(url.fragment) not in anchors_for(target)
                and url.fragment != "top"
            ):
                errors.append(f"{rel}: missing anchor '{href}'")

    if not args.offline:
        with ThreadPoolExecutor(max_workers=args.workers) as pool:
            results = pool.map(lambda u: check_external(u, args.timeout), external)
            for link, error in zip(external, results, strict=False):
                if error:
                    sources = ", ".join(sorted({str(s) for s in external[link]}))
                    errors.append(f"{sources}: {link} ({error})")

    for error in errors:
        argv0 = os.path.basename(__file__)
        print(f"{argv0}: {error}", file=sys.stderr)
    checked = len(external) if not args.offline else 0
    print(f"check_links: {len(html_files)} files, {checked} external URLs, {len(errors)} problems")
    return 1 if errors else 0


if __name__ == "__main__":
    sys.exit(main())
